/**
 * Application environment.
 *
 * Phase 1 binds only the existing D1 database and the two SQLite-backed
 * Durable Object namespaces. Secrets (B2, TOTP, conversation keys, Web Push)
 * follow the names from PROJECT_SPEC.md Section 2.6 and are added as they
 * are actually used by later phases.
 *
 * Runtime types come from `worker-configuration.d.ts` (generated by
 * `wrangler types`) and describe D1Database / DurableObjectNamespace / Env.
 */
export interface AppEnv {
  DB: D1Database;
  CONVERSATION_ROOM: DurableObjectNamespace<
    import("../do/conversation-room").ConversationRoomDO
  >;
  USER_PRESENCE: DurableObjectNamespace<import("../do/user-presence").UserPresenceDO>;

  APP_ORIGIN?: string;
  UI_ORIGIN?: string;
  PAGES_ORIGIN?: string;
  CHATSPACE_ORIGIN?: string;
  TURNSTILE_SITE_KEY?: string;
  TURNSTILE_SECRET_KEY?: string;
  SESSION_SIGNING_SECRET?: string;
  TOTP_ENCRYPTION_KEY?: string;
  CONVERSATION_KEY_ENCRYPTION_KEY?: string;
  B2_KEY_ID?: string;
  B2_APPLICATION_KEY?: string;
  B2_BUCKET_ID?: string;
  B2_BUCKET_NAME?: string;
  FREE_STORAGE_BYTES?: string;
  IMAGE_MAX_BYTES?: string;
  FILE_MAX_BYTES?: string;
  B2_DOWNLOAD_TTL_SECONDS?: string;
  WEB_PUSH_VAPID_PRIVATE_KEY?: string;
  QA_GATE_KEY?: string;
}
